-- Tests for Module:ltc-pron/predict. Generated by scripts/make_testcases.py in
-- https://github.com/iwsfutcmd/ltc-pron; run with
-- {{#invoke:ltc-pron/predict/testcases|run_tests}}.

local tests = require("Module:UnitTests")
local m_pron = require("Module:ltc-pron")
local m_predict = require("Module:ltc-pron/predict")
local data = mw.loadData("Module:ltc-pron/data")

local function plain(jyutping)
	return jyutping and (jyutping:gsub("<sup>(%d)</sup>", "%1")) or "–"
end

-- Check the literary and colloquial Cantonese reflexes of one MC reading,
-- written as in Module:zh/data/ltc-pron. "–" means no colloquial form.
local function check(self, char, reading, literary, colloquial, note)
	local initial, final = m_pron.infer_categories(reading)
	local tone = data.tone_number[mw.ustring.sub(reading, 6, 6)]
	self:equals({ char, reading, "literary", note },
		plain(m_predict.predict_yue(initial, final, tone)), literary)
	self:equals({ char, reading, "colloquial", note },
		plain(m_predict.predict_yue_coll(initial, final, tone)), colloquial)
end


-- Readings the live module already gets right
function tests:test_unchanged()
	check(self, "東", "端東一開 平德紅", "dung1", "–", "")
	check(self, "開", "溪咍一開 平苦哀", "hoi1", "–", "溪 > h-")
	check(self, "口", "溪侯一開 上苦后", "hau2", "–", "")
	check(self, "苦", "溪模一開 上康杜", "fu2", "–", "溪 > f- when rounded")
	check(self, "分", "幫文三合 平府文", "fan1", "–", "輕唇化")
	check(self, "凡", "並凡三合 平符咸", "faan4", "–", "-m > -n after labials")
	check(self, "五", "疑模一開 上疑古", "ng5", "–", "syllabic ng")
	check(self, "地", "定脂三開 去徒四", "dei6", "–", "")
	check(self, "知", "知支三開 平陟移", "zi1", "–", "")
	check(self, "機", "見微三開 平居依", "gei1", "–", "")
end

-- Literary fixes
function tests:test_literary()
	check(self, "鄰", "來眞三開 平力珍", "leon4", "–", "眞 after 來")
	check(self, "栗", "來眞三開 入力質", "leot6", "–", "質 after 來")
	check(self, "進", "精眞三開 去即刃", "zeon3", "–", "眞 after 精組")
	check(self, "七", "清眞三開 入親吉", "cat1", "–", "精組 entering keeps -at")
	check(self, "罰", "並元三合 入房越", "fat6", "–", "月合 after voiced labials")
	check(self, "發", "幫元三合 入方伐", "faat3", "–", "voiceless labials keep -aat")
	check(self, "集", "從侵三開 入秦入", "zaap6", "–", "緝 after 從")
	check(self, "決", "見先四合 入古穴", "kyut3", "–", "no gyut")
	check(self, "括", "見桓一合 入古活", "kut3", "–", "no gut")
	check(self, "遏", "影寒一開 入烏葛", "aat3", "–", "no ot")
	check(self, "俖", "滂咍一開 上普乃", "pui2", "–", "no poi")
	check(self, "或", "匣登一合 入胡國", "waak6", "–", "no wak")
	check(self, "事", "崇之三開 去鉏吏", "si6", "–", "崇 before 止")
	check(self, "柿", "崇之三開 上鉏里", "si6", "ci5", "崇 before 止; colloquial keeps the 全濁上 aspirate")
	check(self, "營", "以清三合 平余傾", "jing4", "–", "以 before 清合")
	check(self, "役", "以清三合 入營隻", "jik6", "–", "以 before 昔合")
	check(self, "卦", "見佳二合 去古賣", "gwaa3", "–", "rounded 佳")
	check(self, "乖", "見皆二合 平古懷", "gwaai1", "–", "rounded 皆 keeps -aai")
	check(self, "卓", "知江二開 入竹角", "zoek3", "–", "覺 after 知")
	check(self, "丘", "溪尤三開 平去鳩", "jau1", "–", "溪 j- rule")
	check(self, "泣", "溪侵三開 入去急-重鈕", "jap1", "–", "溪 j- rule")
	check(self, "卻", "溪陽三開 入去約", "koek3", "–", "no hoek")
end

-- Colloquial reflexes
function tests:test_colloquial()
	check(self, "生", "生庚二開 平所庚", "sang1", "saang1", "梗攝 II")
	check(self, "白", "並庚二開 入傍陌", "bak6", "baak6", "梗攝 II")
	check(self, "客", "溪庚二開 入苦格", "hak1", "haak3", "梗攝 II, mid entering tone")
	check(self, "病", "並庚三開 去皮命", "bing6", "beng6", "梗攝 III–IV")
	check(self, "石", "常清三開 入常隻", "sik6", "sek6", "梗攝 III–IV")
	check(self, "尺", "昌清三開 入昌石", "cik1", "cek3", "梗攝 III–IV, mid entering tone")
	check(self, "迎", "疑庚三開 平語京", "jing4", "jeng4", "疑 stays j-")
	check(self, "重", "澄鍾三開 上直隴", "zung6", "cung5", "全濁上")
	check(self, "舅", "群尤三開 上其九", "gau6", "kau5", "全濁上")
	check(self, "市", "常之三開 上時止", "si6", "si5", "全濁上, fricative")
	check(self, "黑", "曉登一開 入呼北", "hak1", "haak1", "德, tone stays 1")
	check(self, "疊", "定添四開 入徒協", "dip6", "daap6", "怗")
	check(self, "四", "心脂三開 去息利", "si3", "sei3", "脂 after 心")
	check(self, "死", "心脂三開 上息姊-重鈕", "si2", "sei2", "脂 after 心, final 17")
	check(self, "艇", "定青四開 上徒鼎", "ding6", "teng5", "梗攝 and 全濁上 together")
end

-- No colloquial form where it would not be a syllable
function tests:test_no_colloquial()
	check(self, "亦", "以清三開 入羊益", "jik6", "–", "*jek6")
	check(self, "寧", "泥青四開 平奴丁", "ning4", "–", "*neng4")
end

return tests
